55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const BLOCK_SIZE = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	
71	const countByType = (items: Item[]): Map<string, number> => {
72	  const counts = new Map<string, number>();
73	  for (const item of items) {
74	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
75	  }
76	  return counts;
77	};
78	
79	const basePremiumOfGroup = (type: string, count: number): number =>
80	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
81	
82	const policyBasePremium = (items: Item[]): number =>
83	  [...countByType(items)].reduce(
84	    (total, [type, count]) => total + basePremiumOfGroup(type, count),
85	    0,
86	  );
87	
88	const firstInsuranceSurcharge = (policyBase: number): number =>
89	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
90	
91	const itemSurcharges = (items: Item[]): number =>
92	  items.reduce(
93	    (total, item) =>
94	      total + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0),
95	    0,
96	  );
97	
98	const quote = (step: QuoteStep): QuoteResult => {
99	  const policyBase = policyBasePremium(step.items);
100	  const premiumBeforeRounding =
101	    policyBase +
102	    itemSurcharges(step.items) +
103	    firstInsuranceSurcharge(policyBase) +
104	    PROCESSING_FEE;
105	  return { premium: Math.ceil(premiumBeforeRounding) };
106	};
107	
108	export const runScenario = (scenario: Scenario): ScenarioOutput => {
109	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
110	};
